const rows = [];
function validate(input) { if (!input || typeof input.label !== 'string') throw new Error('label-required'); }
async function persist(input) { const row = {id: rows.length + 1, label: input.label}; rows.push(row); return row; }
exports.save = async input => { validate(input); return persist(input); };
